import numpy as np
from scipy.optimize import linear_sum_assignment

class PersonTracker:
    def __init__(self, parameters):
        self.tracks = []
        self.next_id = parameters['initial_track_id']
        self.iou_threshold = parameters['iou_threshold']
        self.max_age = parameters['max_age']

    def iou(self, box_a, box_b):
        ax1, ay1, ax2, ay2 = box_a
        bx1, by1, bx2, by2 = box_b
        ix1, iy1 = max(ax1, bx1), max(ay1, by1)
        ix2, iy2 = min(ax2, bx2), min(ay2, by2)
        inter = max(0, ix2 - ix1) * max(0, iy2 - iy1)
        area_a = max(0, ax2 - ax1) * max(0, ay2 - ay1)
        area_b = max(0, bx2 - bx1) * max(0, by2 - by1)
        union = area_a + area_b - inter
        return inter / union if union > 0 else 0.0

    def new_track(self, detection):
        track = {'id': self.next_id, 'box': detection['box'], 'score': detection['score'], 'class': detection['class'], 'misses': 0, 'hits': 1}
        self.next_id += 1
        return track

    def update(self, packet):
        detections = packet['detections']
        if not self.tracks:
            for det in detections:
                self.tracks.append(self.new_track(det))
        else:
            if detections:
                cost = np.zeros((len(self.tracks), len(detections)))
                for i, trk in enumerate(self.tracks):
                    for j, det in enumerate(detections):
                        cost[i, j] = 1 - self.iou(trk['box'], det['box'])
                row_idx, col_idx = linear_sum_assignment(cost)
            else:
                row_idx, col_idx = np.array([], dtype=int), np.array([], dtype=int)
            matched_tracks, matched_dets = set(), set()
            for r, c in zip(row_idx, col_idx):
                if 1 - cost[r, c] >= self.iou_threshold:
                    trk, det = self.tracks[r], detections[c]
                    trk['box'] = det['box']
                    trk['score'] = det['score']
                    trk['class'] = det['class']
                    trk['hits'] += 1
                    trk['misses'] = 0
                    matched_tracks.add(r)
                    matched_dets.add(c)
            for i, trk in enumerate(self.tracks):
                if i not in matched_tracks:
                    trk['misses'] += 1
            for j, det in enumerate(detections):
                if j not in matched_dets:
                    self.tracks.append(self.new_track(det))
            self.tracks = [trk for trk in self.tracks if trk['misses'] <= self.max_age]
        objects = [{'track_id': trk['id'], 'class': trk['class'], 'confidence': float(trk['score']), 'bbox': [float(v) for v in trk['box']]} for trk in self.tracks if trk['misses'] == 0]
        return {'frame_index': packet['frame_index'], 'timestamp_s': packet['timestamp_s'], 'width': packet['width'], 'height': packet['height'], 'objects': objects}

parameters = {'method': 'multi-object tracking', 'iou_threshold': 0.3, 'max_age': 15, 'initial_track_id': 1}
tracker = PersonTracker(parameters)
def process(detection_packet):
    return tracker.update(detection_packet)
